/* plan review */
#plv{max-width:560px}
.plv-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:14px 16px;border-bottom:1px solid var(--line)}
.plv-head .t{display:block;font-weight:600;font-size:14px}
.plv-goal{display:block;margin-top:2px;font-size:13px;color:var(--text-dim)}
.plv-list{list-style:none;margin:0;padding:6px 0}
.plv-row{display:flex;align-items:center;gap:12px;padding:8px 16px;font-size:13px;color:var(--text);transition:color .3s,opacity .3s}
.plv-row .st{width:20px;height:20px;flex:none;display:grid;place-items:center;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted)}
.plv-row .tx{flex:1;min-width:0;outline:none;padding:2px 4px;margin:-2px -4px}
.plv-row .tag{color:var(--text-dim)}
.plv-row .mv{display:none;gap:4px}
.plv-row .mv button{width:24px;height:24px;display:grid;place-items:center;color:var(--muted);transition:color .2s,background .2s}
.plv-row .mv button:hover{color:var(--text);background:var(--chip)}
#plv.editing .plv-row .mv{display:flex}
#plv.editing .plv-row .tx{background:var(--chip);cursor:text}
#plv.editing .plv-row .tag{display:none}
.plv-row.done .tx{color:var(--text-dim)}
.plv-row.out{opacity:0}
.plv-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;border-top:1px solid var(--line)}
.plv-add{display:inline-flex;align-items:center;gap:6px;font-size:13px;color:var(--muted);opacity:0;pointer-events:none;transition:opacity .25s,color .2s}
.plv-add:hover{color:var(--text)}
#plv.editing .plv-add{opacity:1;pointer-events:auto}
.plv-acts{display:flex;gap:8px}
.plv-acts .btn{padding:8px 12px;font-size:13px}

/* ---------- plan review ---------- */
{
  const root = $('#plv'), list = $('#plv-list'), sum = $('#plv-sum'), edit = $('#plv-edit'), go = $('#plv-go');
  const base = [['Find every billing email template','Search'],['Compare each one with the new layout','Read'],['Rewrite the copy to fit the new blocks','Edit'],['Send test emails to the billing team','Email'],['Switch the live templates over','Deploy']];
  let ts = [], running = false;
  const rows = () => $$('.plv-row', list);
  function number(){
    rows().forEach((r, i) => { if (!r.classList.contains('done') && !r.querySelector('.spin')) r.querySelector('.st').textContent = String(i + 1).padStart(2, '0'); });
    if (!running) swapText(sum, `Draft, ${rows().length} steps`);
  }
  function row(text, tool){
    const li = document.createElement('li'); li.className = 'plv-row';
    li.innerHTML = `<span class="st"></span><span class="tx">${text}</span><span class="tag">${tool}</span><span class="mv"><button data-up title="Move up">${ic('arrow_upward','sm')}</button><button data-rm title="Remove step">${ic('close','sm')}</button></span>`;
    return li;
  }
  function setEditing(on){
    root.classList.toggle('editing', on);
    rows().forEach(r => r.querySelector('.tx').contentEditable = on ? 'true' : 'false');
    edit.textContent = on ? 'Done' : 'Edit plan';
    go.disabled = on;
  }
  function reset(){
    ts.forEach(clearTimeout); ts = []; running = false;
    list.innerHTML = ''; base.forEach(b => list.appendChild(row(...b)));
    setEditing(false); edit.disabled = false; go.disabled = false; go.textContent = 'Approve and run';
    number();
  }
  list.addEventListener('click', e => {
    const b = e.target.closest('button'); if (!b || !root.classList.contains('editing')) return;
    const r = b.closest('.plv-row');
    if (b.hasAttribute('data-up') && r.previousElementSibling){ list.insertBefore(r, r.previousElementSibling); Sound.play('tab'); }
    if (b.hasAttribute('data-rm') && rows().length > 1){ r.classList.add('out'); Sound.play('pop'); setTimeout(() => { r.remove(); number(); }, 250); }
    number();
  });
  $('#plv-add').addEventListener('click', () => {
    const r = row('New step', 'Task'); list.appendChild(r); r.classList.add('enter');
    const tx = r.querySelector('.tx'); tx.contentEditable = 'true'; tx.focus();
    getSelection().selectAllChildren(tx); Sound.play('tab'); number();
  });
  edit.addEventListener('click', () => { Sound.play('tab'); setEditing(!root.classList.contains('editing')); });
  go.addEventListener('click', () => {
    if (running) return; running = true; Sound.play('tab');
    go.disabled = true; edit.disabled = true; go.textContent = 'Running';
    const rs = rows();
    rs.forEach((r, i) => {
      ts.push(setTimeout(() => {
        swapText(sum, `Running, step ${i + 1} of ${rs.length}`);
        r.querySelector('.st').innerHTML = '<i class="spin"></i>';
      }, i * 900));
      ts.push(setTimeout(() => {
        r.classList.add('done'); r.querySelector('.st').innerHTML = ic('check_circle', 'sm icon-in s-done');
        ambient('c105', 'tick');
        if (i === rs.length - 1){ swapText(sum, `Done, ${rs.length} of ${rs.length} steps`); go.textContent = 'Approved'; Sound.play('done'); }
      }, i * 900 + 760));
    });
  });
  $('#plv-reset').addEventListener('click', () => { Sound.play('tab'); reset(); });
  reset();
}
